import {useMediaQuery} from "../../../shared/index";

import {useEffect} from "react";
import {useDispatch} from "react-redux";
import {uiSettingsActions} from "../UISettings.slice";

const useResponsiveMode=()=>{
    const dispatch = useDispatch();
    const isMobile = useMediaQuery('(max-width: 50rem)' );
    const isTablet = useMediaQuery('(min-width: 50.1rem) and (max-width: 85rem)' );
    const isDesktop = useMediaQuery('(min-width: 85.1rem)' );
    useEffect(() => {
        if (isMobile) {
            dispatch(uiSettingsActions.setResponsiveMode({ mode: "mobile", rate: 1.2 }));
        } else if (isTablet) {
            dispatch(uiSettingsActions.setResponsiveMode({ mode: "tablet", rate: 1.2 }));
        } else if (isDesktop) {
            dispatch(uiSettingsActions.setResponsiveMode({ mode: "desktop", rate: 1 }));
        }
    }, [isMobile, isTablet, isDesktop, dispatch]);

    return null;


}

export default useResponsiveMode;