import React, {useEffect} from 'react';
import {HoldButton, SpeechRecognition, useSpeechRecognition, languages, BurgerMenu} from "./index";

import css from "./SpeechToText.module.css";
import {SpeechToTextChangeLanguage} from "./index";
import {useLangStore} from "./hook/useLangStore";

const SpeechToText = (props) => {
    const {onTranscriptChange} = props;
    const {transcript, listening, resetTranscript} = useSpeechRecognition();

    const [lang] = useLangStore()

    const startListening = () => {
        resetTranscript();
        SpeechRecognition.startListening({continuous: true, lang})
    }

    const stopListening = () => {
        SpeechRecognition.stopListening();
    }

    useEffect(() => {
        onTranscriptChange(transcript)
    }, [transcript, onTranscriptChange]);

    return (
        <div className={[css.speech_to_text, listening ? css.hold_microphone : ""].join(" ")}>
            <SpeechToTextChangeLanguage languages={languages}/>

            <HoldButton onAction={startListening} offAction={stopListening}>Start</HoldButton>
            <HoldButton onAction={startListening} offAction={stopListening}><BurgerMenu/></HoldButton>
        </div>
    );
};

export {SpeechToText};