import React, {useState} from 'react';

import {useIsTouchDevice} from "../index";
import css from "./HoldButton.module.css"

const HoldButton = ({children, onAction, offAction}) => {
    const [hover, setHover] = useState(false)

    const holdOn = () => {
        if (typeof onAction ==="function") onAction();
        setHover(true)
    }
    const holdOff = () => {
        if (typeof offAction === "function") offAction();
        setHover(false)
    }

    const getProperties = (isTrue) => {
        const obj = {
            true: {onTouchStart: holdOn, onTouchEnd: holdOff},
            false: {onMouseDown: holdOn, onMouseUp: holdOff}
        }
        return obj[isTrue]
    }

    return (
        <button
            className={[css.btn, "noselect", hover ? css.hover : ""].join(" ")} {...getProperties(useIsTouchDevice())}>
            {children}
        </button>
    );
};

export {HoldButton};

