import {configureStore} from "@reduxjs/toolkit";
import {uiSettingsReducer} from "../features/ResponsiveDesign/UISettings.slice";
import {appConstants} from "../shared/constants/appConstants";

const {localStorageKeyFontSize,localStorageKeyTheme} = appConstants;

const store = configureStore({
    reducer: {
        uiSettings: uiSettingsReducer,
    },
    middleware: (getDefaultMiddleware) =>
        getDefaultMiddleware({
            serializableCheck: false,
        }),
})

store.subscribe(() => {
    localStorage.setItem(localStorageKeyFontSize, JSON.stringify(store.getState().uiSettings.fontSize));
    localStorage.setItem(localStorageKeyTheme, JSON.stringify(store.getState().uiSettings.theme));
})

export {store};