import {createHashRouter, Navigate} from "react-router-dom";
import {HomePage} from "./Pages/HomePage";
import {ResponsiveDesign} from "./features/ResponsiveDesign/ResponsiveDesign";
import { SpeechToTextPage} from "./Pages/SpeechRecognition.page";


const router = createHashRouter([
    {path:"/",element:<ResponsiveDesign/>,children:[
            {index:true,element:<Navigate to={"home"} replace/>},
            {path:"home",element:<HomePage/>},
            {path:"speech",element:<SpeechToTextPage/>},
            {path: "*", element: <h1>NoPage</h1>}
        ]}
])

export default router;