import React, {useState} from 'react';

import {useSelector} from "react-redux";

import {NavbarItem} from "./NavbarItem";
import {WithHover} from "./hoc/WithHover";
import css from "./Navbar.module.css"
import {HoverAbleBackArrow} from "./Components/HoverAbleBackArrow";

const Navbar = (props) => {
    const {items, tooltipShow, setTooltipShow} = props;
    const {mode} = useSelector(state => state.uiSettings);
    const [isFocused, setIsFocused] = useState(0);
    let isArrowBack = false

    const classTooltip = [css.tooltip];

    if (tooltipShow) {
        classTooltip.push(css.active);
        isArrowBack = true;
    }

    if (!tooltipShow && Boolean(isFocused)) {
        classTooltip.push(css.hoverTooltip);
        isArrowBack = false;
    }

    const renderBackArrow = (title) => {
        return (
            <WithHover setIsFocused={setIsFocused}
                       onClick={() => setTooltipShow(prev => !prev)}>
                <HoverAbleBackArrow title={title} classTooltip={classTooltip} tooltipShow={tooltipShow} isArrowBack={isArrowBack}/>
            </WithHover>
        )
    }


    return (
        <>
            <div className={css.Navbar}>
                {mode === "tablet" ? renderBackArrow( isArrowBack? "Collapse":"Expand") : null}
                {items.map((item, index) => <NavbarItem key={index} isArrowBack={isArrowBack} item={item}
                                                        tooltipShow={tooltipShow} depthLevel={0}/>)}
            </div>
        </>
    );
};

export {Navbar};
