import React, {useEffect, useState} from 'react';
import {useSelector} from "react-redux";

import css from "../ResponsiveDesign.module.css"
import {Navbar} from "../../Navbar/Navbar";
import useNavLinksConfig from "../../Navbar/config/menuNavLinks.config";

const Sidebar = () => {

    const {isSideBarOpen, mode} = useSelector(state => state.uiSettings);
    const [tooltipShow, setTooltipShow] = useState(false)

    const classSidebar = [css.side_bar, css[`side_bar_${mode}`]];

    useEffect(() => {
        if (mode !== "tablet") {
            setTooltipShow(true)
        } else setTooltipShow(false);
    }, [mode]);


    if (mode === "mobile" && isSideBarOpen) {
        classSidebar.push(css.side_bar_show)
    }
    if (mode === "tablet" && tooltipShow) {
        classSidebar.push(css.tooltip_show)
    }
    const mapTransition = {
        tablet: "width 1s ease",
        mobile: 'transform 1s linear'
    }

    const navLinks = useNavLinksConfig();

    const styleSidebar = {
        transition: mapTransition[mode]
    };

    return (
        <aside className={classSidebar.join(" ")} style={styleSidebar}>
            <Navbar items={navLinks} setTooltipShow={setTooltipShow} tooltipShow={tooltipShow}/>
        </aside>

    );

};

export {Sidebar};