import React from 'react';
import {useDispatch, useSelector} from "react-redux";
import {uiSettingsActions} from "../UISettings.slice";

import {BurgerMenu, HoldButton} from "../../../shared/index";
import css from "../ResponsiveDesign.module.css"

const Header = () => {
    const {isSideBarOpen: isOpen, mode} = useSelector(state => state.uiSettings)
    const dispatch = useDispatch();

    const toggleSideBar = () => {
        dispatch(uiSettingsActions.toggleSideBar())
    }

    return (
        <header className={css.header}>

            {mode === "mobile" &&
                <HoldButton onAction={toggleSideBar}>
                    {/*<BurgerMenu isOpen={isOpen} setIsOpen={toggleSideBar}/>*/}
                        <BurgerMenu isOpen={isOpen}/>
                </HoldButton>
            }
        </header>
    );
};

export {Header};