import React, {useState} from 'react';

import css from "./Dropdown.module.css"

const Dropdown = (props) => {
    const {
        options = {}, value = null, onChange, children
    } = props;
    const [isDropdown, setIsDropdown] = useState(false);
    const toggleDropdown = () => {
        setIsDropdown(prev => !prev);
    }
    const handleOptionalClick = (value) => {
        if (typeof onChange === "function") onChange(value);
        setIsDropdown(false);
    }

    const childrenWithProps = React.Children.map(children, (child) =>
        React.cloneElement(child, {active: isDropdown})
    );
    if (!Object.keys(options).length) return null

    return (
        <div className={css.dropdown}>
            <div className={css.label} onClick={toggleDropdown}>
                {value}
                {childrenWithProps}
            </div>

            <div className={[css.dropdown_menu, isDropdown ? css.expanded : css.collapsed].join(" ")}>
                {Object.keys(options)
                    .filter(key => options[key] !== value)
                    .map(key => <div key={key}
                                     onClick={() => handleOptionalClick(options[key])}>{options[key]}</div>)}

            </div>
        </div>
    );
};

export {Dropdown};