import {createSlice} from "@reduxjs/toolkit";
import {appConstants} from "../../shared/constants/appConstants";


const {localStorageKeyFontSize, localStorageKeyTheme, availableThemes} = appConstants;

let fontSize = Number(localStorage.getItem(localStorageKeyFontSize)) || 16;
fontSize = (fontSize < 10 || fontSize > 30) ? 16 : fontSize;
const initTheme = () => {
    const localStorageTheme = localStorage.getItem(localStorageKeyTheme)
    if (availableThemes && availableThemes.includes(localStorageTheme)) {
        return localStorageTheme
    } else return availableThemes[0];
}

const initialState = {
    fontSize,
    isSideBarOpen: false,
    theme: initTheme(),
    mode: "mobile",
    rate: 1.5,
}

const uiSettingsSlice = createSlice({
    name: "uiSettings",
    initialState,
    reducers: {
        setFontSize: (state, action) => {
            state.fontSize = action.payload;
        },
        toggleSideBar: (state) => {
            state.isSideBarOpen ^= true;
        },
        setResponsiveMode: (state, action) => {
            state.mode = action.payload.mode;
            state.rate = action.payload.rate;
        },
        setTheme: (state, action) => {
            state.theme = action.payload
        }
    }
})

const {reducer: uiSettingsReducer, actions} = uiSettingsSlice;

const uiSettingsActions = {...actions};

export {uiSettingsActions, uiSettingsReducer}