import {useState} from "react";
import {useDispatch, useSelector} from "react-redux";
import {uiSettingsActions} from "../UISettings.slice";

import {appConstants} from "../../../shared/constants/appConstants";


const {fontSizeMax, fontSizeMin, fontSizeStep} = appConstants;

const FontSizeChanger = () => {

    const initFontSize = useSelector(state => state.uiSettings.fontSize)
    const [fontSize, setFontSize] = useState(initFontSize);
    const dispatch = useDispatch();
    const handleChange = (e) => {
        const value = e.target.value;
        setFontSize(value);
        dispatch(uiSettingsActions.setFontSize(value))
    }
    return (

        <div style={{display: "flex",alignItems:"flex-start",justifyContent:"center"}}>

            <label htmlFor="fontsize">FontSize</label>
           <div className="icon">
            <input id="fontsize" type="range"
                   min={fontSizeMin}
                   max={fontSizeMax}
                   step={fontSizeStep}
                   value={Number(fontSize) || 16}
                   onChange={(e) => handleChange(e)}
            />
           </div>
        </div>
    );
};

export {FontSizeChanger};
